    private long firstClickTimestamp = 0;
    private boolean windowOpen = false;
    private long lastWindowOpenTimestamp = 0;

    private List<double[]> distanceTime = new ArrayList<>();
    private List<double[]> slotTime = new ArrayList<>();
  }
